class Stream { constructor(buf) { this.buf = buf; } }

class FileStream extends Stream {
  constructor(fd) {
    const buf = Buffer.forFd(fd);   // before super(): no `this` yet
    super(buf);                     // the dependent "base" gets the payload
    this.buf = buf;                 // same value, now the object's own data
  }
}
